import fs from 'fs';
import path from 'path';

// Import the createScene function from the object file
import { createScene } from './data/object.js';

const PART_MESHES_DIR = '/root/output/part_meshes';
const LINKS_DIR = '/root/output/links';

// Create output directories
fs.mkdirSync(PART_MESHES_DIR, { recursive: true });
fs.mkdirSync(LINKS_DIR, { recursive: true });

// Build the scene
const root = createScene();

// Update all world matrices so transforms are baked correctly
root.updateMatrixWorld(true);

const exporter = new OBJExporter();

/**
 * Export a single mesh to OBJ, applying its full world transform.
 * We create a temporary scene with a clone of the mesh so OBJExporter
 * writes it properly.
 */
function exportMeshToOBJ(mesh) {
    // Clone geometry and apply world transform
    const clonedGeom = mesh.geometry.clone();
    clonedGeom.applyMatrix4(mesh.matrixWorld);

    // Ensure normals exist
    if (!clonedGeom.getAttribute('normal')) {
        clonedGeom.computeVertexNormals();
    }

    const tempMesh = new THREE.Mesh(clonedGeom);
    tempMesh.name = mesh.name;

    const tempScene = new THREE.Scene();
    tempScene.add(tempMesh);

    return exporter.parse(tempScene);
}

/**
 * Export all meshes in a group (recursively) into a single combined OBJ file.
 * This is used for the "links" output - one file per part with all its meshes.
 */
function exportGroupToOBJ(group) {
    // Clone the entire group, but we need to apply world transforms
    const tempScene = new THREE.Scene();

    group.traverse((child) => {
        if (child.isMesh) {
            const clonedGeom = child.geometry.clone();
            clonedGeom.applyMatrix4(child.matrixWorld);
            if (!clonedGeom.getAttribute('normal')) {
                clonedGeom.computeVertexNormals();
            }
            const tempMesh = new THREE.Mesh(clonedGeom);
            tempMesh.name = child.name;
            tempScene.add(tempMesh);
        }
    });

    return exporter.parse(tempScene);
}

/**
 * Recursively find all "part" groups and their meshes.
 * A "part" is a THREE.Group that is a direct child of the root,
 * or a sub-group within a part (like cabin groups inside wheel_structure).
 */
function findParts(node) {
    const parts = [];

    for (const child of node.children) {
        if (child.isGroup) {
            // This is a part group
            parts.push(child);
            // Also look for sub-groups (e.g., cabin groups inside wheel_structure)
            for (const grandchild of child.children) {
                if (grandchild.isGroup) {
                    parts.push(grandchild);
                }
            }
        }
    }

    return parts;
}

