parts.forEach(p => {
    const meshCount = p.children.filter(c => c.isMesh).length;
    const groupCount = p.children.filter(c => c.isGroup).length;
    console.log(`  - ${p.name}: ${meshCount} meshes, ${groupCount} sub-groups`);
